## Fix: Enable CloudWatch Logs Integration for CloudTrail

Configure your CloudTrail trail to send logs to a CloudWatch Logs group by setting both the log group ARN and the IAM role ARN:

```typescript
import * as aws from "@pulumi/aws";

// Create a CloudWatch Logs group for CloudTrail
const cloudtrailLogGroup = new aws.cloudwatch.LogGroup("cloudtrail-logs");

// Create an IAM role for CloudTrail to write to CloudWatch Logs
const cloudtrailRole = new aws.iam.Role("cloudtrail-cloudwatch-role", {
    assumeRolePolicy: JSON.stringify({
        Version: "2012-10-17",
        Statement: [{
            Effect: "Allow",
            Principal: { Service: "cloudtrail.amazonaws.com" },
            Action: "sts:AssumeRole",
        }],
    }),
});

// Attach policy to allow CloudTrail to write logs
const cloudtrailPolicy = new aws.iam.RolePolicy("cloudtrail-cloudwatch-policy", {
    role: cloudtrailRole.id,
    policy: pulumi.all([cloudtrailLogGroup.arn]).apply(([logGroupArn]) => JSON.stringify({
        Version: "2012-10-17",
        Statement: [{
            Effect: "Allow",
            Action: ["logs:CreateLogStream", "logs:PutLogEvents"],
            Resource: `${logGroupArn}:*`,
        }],
    })),
});

const trail = new aws.cloudtrail.Trail("my-trail", {
    s3BucketName: trailBucket.id,
    cloudWatchLogsGroupArn: cloudtrailLogGroup.arn,  // Set the log group ARN
    cloudWatchLogsRoleArn: cloudtrailRole.arn,       // Set the IAM role ARN
});
```

